<?php
declare(strict_types=1);require __DIR__.'/../app/bootstrap.php';if(is_file(__DIR__.'/../app/access_control_v1300.php'))require_once __DIR__.'/../app/access_control_v1300.php';require_once __DIR__.'/../app/services_v1380.php';$p=sk1380_require_provider();$ent=sk1380_entitlements((int)$p['id']);$services=sk1380_provider_services((int)$p['id']);$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{sk1380_csrf_check();$act=(string)$_POST['action'];if($act==='use_slot'){$sid=(int)$_POST['offering_id'];if($ent['featured_slots']<1)throw new RuntimeException('Your package has no featured service slots.');$q=sk1380_db()->prepare('SELECT COUNT(*) FROM service_offerings_v1380 WHERE tenant_id=? AND provider_id=? AND featured_until>NOW()');$q->execute([sk1380_tid(),$p['id']]);if((int)$q->fetchColumn()>=$ent['featured_slots'])throw new RuntimeException('All package featured slots are already in use.');$slotEnd=date('Y-m-d H:i:s',strtotime('+30 days'));if(!empty($p['package_ends_at'])&&strtotime((string)$p['package_ends_at'])<strtotime($slotEnd))$slotEnd=(string)$p['package_ends_at'];$q=sk1380_db()->prepare('UPDATE service_offerings_v1380 SET featured_until=?,updated_at=NOW() WHERE tenant_id=? AND provider_id=? AND id=? AND active=1');$q->execute([$slotEnd,sk1380_tid(),$p['id'],$sid]);if(!$q->rowCount())throw new RuntimeException('Service not found.');$msg='Package featured slot activated for 30 days.';}elseif($act==='request_paid'){$type=(string)$_POST['promotion_type'];$map=['featured_provider'=>'services_promo_featured_provider_price','priority_search'=>'services_promo_priority_search_price','featured_service'=>'services_promo_featured_service_price'];if(!isset($map[$type]))throw new RuntimeException('Invalid promotion.');$price=(float)sk1380_setting($map[$type],'0');if($price<=0)throw new RuntimeException('Admin has not enabled pricing for this promotion yet.');$ref=trim((string)$_POST['payment_reference']);if($ref==='')throw new RuntimeException('Payment/reference number is required.');$sid=$type==='featured_service'?(int)($_POST['offering_id']??0):null;if($sid){$q=sk1380_db()->prepare('SELECT 1 FROM service_offerings_v1380 WHERE tenant_id=? AND provider_id=? AND id=? AND active=1');$q->execute([sk1380_tid(),$p['id'],$sid]);if(!$q->fetchColumn())throw new RuntimeException('Service not found.');}sk1380_db()->prepare('INSERT INTO service_promotions_v1380(tenant_id,provider_id,offering_id,promotion_type,amount_snapshot,payment_reference,status,created_at,updated_at) VALUES(?,?,?,?,?,?,"pending",NOW(),NOW())')->execute([sk1380_tid(),$p['id'],$sid,$type,$price,$ref]);$msg='Promotion request sent for admin payment verification.';}}catch(Throwable $e){$err=$e->getMessage();}}$q=sk1380_db()->prepare('SELECT * FROM service_promotions_v1380 WHERE tenant_id=? AND provider_id=? ORDER BY id DESC LIMIT 50');$q->execute([sk1380_tid(),$p['id']]);$rows=$q->fetchAll(PDO::FETCH_ASSOC)?:[];$prices=['featured_provider'=>(float)sk1380_setting('services_promo_featured_provider_price','0'),'priority_search'=>(float)sk1380_setting('services_promo_priority_search_price','0'),'featured_service'=>(float)sk1380_setting('services_promo_featured_service_price','0')];sk1380_shell('Service Promotions','promotions');?><section class="dash-hero"><div><span class="eyebrow">FEATURED & SEARCH TOOLS</span><h1>Provider Promotions</h1><p>Package benefits and additional paid promotions are separate. Paid promotions activate only after admin verifies the submitted reference.</p></div><a href="/provider/services.php">Dashboard</a></section><?php if($msg):?><div class="notice ok"><?=sk1380_h($msg)?></div><?php endif;?><?php if($err):?><div class="notice err"><?=sk1380_h($err)?></div><?php endif;?><div class="package-grid"><article><span>PACKAGE BENEFIT</span><h2><?=$ent['featured_slots']?> Featured Slots</h2><p>Use your active package slots on individual services.</p><form method="post"><input type="hidden" name="_csrf" value="<?=sk1380_h(sk1380_csrf())?>"><input type="hidden" name="action" value="use_slot"><select name="offering_id"><?php foreach($services as $s):?><option value="<?=$s['id']?>"><?=sk1380_h($s['title'])?></option><?php endforeach;?></select><button>Feature Service with Package Slot</button></form></article><?php foreach(['featured_provider'=>'Featured Provider','priority_search'=>'Priority Search','featured_service'=>'Featured Service'] as $key=>$label):?><article><span>PAID PROMOTION</span><h2><?=sk1380_h($label)?></h2><p><?=$prices[$key]>0?'PKR '.number_format($prices[$key],0).' / 30 days':'Price not enabled by admin'?></p><?php if($prices[$key]>0):?><form method="post"><input type="hidden" name="_csrf" value="<?=sk1380_h(sk1380_csrf())?>"><input type="hidden" name="action" value="request_paid"><input type="hidden" name="promotion_type" value="<?=sk1380_h($key)?>"><?php if($key==='featured_service'):?><select name="offering_id"><?php foreach($services as $s):?><option value="<?=$s['id']?>"><?=sk1380_h($s['title'])?></option><?php endforeach;?></select><?php endif;?><input name="payment_reference" required placeholder="Payment / transaction reference"><button>Submit for Admin Verification</button></form><?php endif;?></article><?php endforeach;?></div><h2>Promotion History</h2><div class="simple-table"><?php foreach($rows as $r):?><div><b><?=sk1380_h(str_replace('_',' ',ucwords($r['promotion_type'],'_')))?></b><span>PKR <?=number_format((float)$r['amount_snapshot'],0)?> · <?=sk1380_h($r['payment_reference'])?></span><strong><?=sk1380_h(strtoupper($r['status']))?></strong></div><?php endforeach;?></div><?php sk1380_end();